// src/lib/illustration_svg.js — Hand-drawn Warm Food Illustration SVG Generator
// Generates high-quality editorial/storybook style vector food illustration (800x800)
// Served whenever images/{code}.png has not been generated by Gemini_foods_이미지자동생성.bat yet.

import { formatFoodCode, FOOD_ORIGIN_GROUPS } from './constants.js';

/**
 * XML 특수문자 이스케이프
 */
function escapeXml(str) {
  if (str == null) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

