/**
 * 음식명 또는 그룹에 따른 자동 대표 이모지 추론 (음식 객체에 emoji가 없을 때 안전 폴백)
 */
export function resolveFoodEmoji(food) {
  if (food?.emoji) return food.emoji;
  const name = String(food?.name || '');
  if (/당근/.test(name)) return '🥕';
  if (/토마토/.test(name)) return '🍅';
  if (/오이/.test(name)) return '🥒';
  if (/사과/.test(name)) return '🍎';
  if (/포도|샤인머스/.test(name)) return '🍇';
  if (/복숭아/.test(name)) return '🍑';
  if (/딸기/.test(name)) return '🍓';
  if (/블루베리/.test(name)) return '🫐';
  if (/고구마/.test(name)) return '🍠';
  if (/아보카도/.test(name)) return '🥑';
  if (/양배추/.test(name)) return '🥬';
  if (/달걀|계란/.test(name)) return '🍳';
  if (/스파게티|파스타|카펠리니/.test(name)) return '🍝';
  if (/라면|라멘|우동|국수|냉면|소바|짜장|짬뽕|쌀국수|마라탕|막국수/.test(name)) return '🍜';
  if (/국|찌개|탕|전골|곰탕|설렁탕|스프|수프/.test(name)) return '🍲';
  if (/밥|솥밥|리조또|볶음밥|비빔밥|덮밥|카레/.test(name)) return '🍚';
  if (/초밥|스시|회|카이센동|연어|게장/.test(name)) return '🍣';
  if (/치킨|통닭|닭/.test(name)) return '🍗';
  if (/스테이크|채끝|등심|한우|소고기|돼지|삼겹살|고기|갈비|제육/.test(name)) return '🥩';
  if (/돈까스|돈카츠|가츠|피카츄/.test(name)) return '🍱';
  if (/버거|햄버거/.test(name)) return '🍔';
  if (/피자/.test(name)) return '🍕';
  if (/만두|교자|딤섬/.test(name)) return '🥟';
  if (/떡볶이|로제/.test(name)) return '🥘';
  if (/빵|토스트|샌드위치|소금빵|크루아상/.test(name)) return '🥐';
  if (/빙수|아이스크림|디저트|케이크|초콜릿|붕어빵|맛탕/.test(name)) return '🍰';
  if (/우니|성게알|캐비어|전복|랍스터|새우|게/.test(name)) return '🦞';

  // Origin Group 폴백
  const origin = food?.originGroup || '';
  if (origin.startsWith('MICHELIN')) return '⭐';
  if (origin === 'SCHOOL_LUNCH') return '🍱';
  if (origin === 'RAW_NATURAL') return '🥕';
  if (origin === 'UNIQUE_SPECIAL' || origin === 'UNIQUE_RESTAURANT') return '🧪';
  if (origin === 'BIB_GOURMAND') return '🏅';
  if (origin === 'KOREAN_POPULAR' || origin === 'KOREAN_FAVORITE') return '🍲';
  return '🍽️';
}

/**
 * 800×800 크기의 따뜻한 손그림 일러스트풍 음식 SVG 생성기
 *
 * @param {object} food - 음식 데이터 객체
 * @param {object} options - 커스텀 옵션 (width, height, isHero 등)
 * @returns {string} 완성된 SVG XML 문자열
 */
export function renderFoodIllustrationSvg(food = {}, options = {}) {
  const originGroup = food.originGroup || 'KOREAN_POPULAR';
  const palette = ORIGIN_PALETTES[originGroup] || ORIGIN_PALETTES.KOREAN_POPULAR;

  const rawIndex = Number(food.index || food.id?.replace(/\D/g, '') || 1);
  const foodCode = formatFoodCode(rawIndex);
  const emoji = resolveFoodEmoji(food);

  const originDef = FOOD_ORIGIN_GROUPS[originGroup];
  const originBadge = food.originBadge || originDef?.badge || '🍽️ 오늘의 추천 메뉴';

  const rawName = String(food.name || '맛있는 오늘의 메뉴');
  const displayName = rawName.length > 22 ? rawName.slice(0, 20) + '…' : rawName;
  const englishName = food.englishName || 'Signature Gourmet Dish';
  const caloriesText = food.calories ? `🔥 ${food.calories}` : '🥗 균형 영양 식단';
  const priceText = food.priceRange ? `🏷️ ${food.priceRange}` : '✨ 특별 맞춤 추천';

  // 음식 고유 번호 기반 결정론적 스파클(별빛/반짝임) 좌표
  const seed = (rawIndex * 2654435761) >>> 0;
  let sparkles = '';
  const starCoords = [
    { cx: 160, cy: 190, r: 4 },
    { cx: 210, cy: 140, r: 2.5 },
    { cx: 620, cy: 170, r: 3.5 },
    { cx: 670, cy: 220, r: 2 },
    { cx: 140, cy: 460, r: 3 },
    { cx: 660, cy: 470, r: 3 }
  ];
  for (let i = 0; i < starCoords.length; i++) {
    const sc = starCoords[i];
    const jitterX = ((seed + i * 37) % 24) - 12;
    const jitterY = ((seed + i * 59) % 24) - 12;
    sparkles += `
    <g transform="translate(${sc.cx + jitterX}, ${sc.cy + jitterY})">
      <path d="M 0 -${sc.r * 2.8} Q 0 0 ${sc.r * 2.8} 0 Q 0 0 0 ${sc.r * 2.8} Q 0 0 -${sc.r * 2.8} 0 Q 0 0 0 -${sc.r * 2.8} Z" fill="${palette.accent}" opacity="0.75" />
    </g>`;
  }

  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 800" width="800" height="800">
  <defs>
    <!-- 배경 그라디언트 -->
    <linearGradient id="bgGrad" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="${palette.bgStart}" />
      <stop offset="100%" stop-color="${palette.bgEnd}" />
    </linearGradient>

    <!-- 플레이트 은은한 조명 -->
    <radialGradient id="dishGlow" cx="50%" cy="46%" r="48%">
      <stop offset="0%" stop-color="${palette.glowColor}" stop-opacity="0.30" />
      <stop offset="60%" stop-color="${palette.glowColor}" stop-opacity="0.08" />
      <stop offset="100%" stop-color="${palette.glowColor}" stop-opacity="0" />
    </radialGradient>

    <!-- 접시 광택 그라디언트 -->
    <linearGradient id="plateShine" x1="20%" y1="0%" x2="80%" y2="100%">
      <stop offset="0%" stop-color="#FFFFFF" stop-opacity="0.28" />
      <stop offset="100%" stop-color="#000000" stop-opacity="0.35" />
    </linearGradient>

    <!-- 하단 카드 그라디언트 -->
    <linearGradient id="cardGrad" x1="0%" y1="0%" x2="0%" y2="100%">
      <stop offset="0%" stop-color="#141419" stop-opacity="0.94" />
      <stop offset="100%" stop-color="#09090C" stop-opacity="0.98" />
    </linearGradient>
  </defs>

  <!-- 메인 배경 캔버스 -->
  <rect width="800" height="800" rx="36" fill="url(#bgGrad)" />

  <!-- 일러스트 외곽 액자 테두리선 -->
  <rect x="24" y="24" width="752" height="752" rx="28" fill="none" stroke="${palette.accent}" stroke-width="2" stroke-opacity="0.35" stroke-dasharray="10 6" />

  <!-- 테이블 중앙 백라이트 광채 -->
  <circle cx="400" cy="360" r="280" fill="url(#dishGlow)" />

  <!-- 결정론적 별빛 스파클 -->
  ${sparkles}

  <!-- 상단 헤더: [출처 뱃지] & [음식 고유 코드] -->
  <g id="top-badges">
    <!-- 출처 뱃지 -->
    <rect x="40" y="44" width="260" height="42" rx="21" fill="${palette.badgeBg}" fill-opacity="0.22" stroke="${palette.badgeBg}" stroke-width="1.5" />
    <text x="170" y="71" text-anchor="middle" fill="#FFFFFF" font-family="'Pretendard', -apple-system, sans-serif" font-size="16" font-weight="700">${escapeXml(originBadge)}</text>

    <!-- 음식 고유 번호 -->
    <rect x="620" y="44" width="140" height="42" rx="21" fill="#000000" fill-opacity="0.45" stroke="#FFFFFF" stroke-opacity="0.25" stroke-width="1.5" />
    <text x="690" y="71" text-anchor="middle" fill="${palette.accent}" font-family="'Pretendard', monospace, sans-serif" font-size="16" font-weight="800">#${escapeXml(foodCode)}</text>
  </g>

  <!-- 손그림풍 식탁 세팅 & 플레이트 아트워크 -->
  <g id="table-setting">
    <!-- 패브릭 식탁 매트 타원 그림자 -->
    <ellipse cx="400" cy="385" rx="280" ry="175" fill="#000000" fill-opacity="0.30" />
    <ellipse cx="400" cy="380" rx="275" ry="170" fill="#FFFFFF" fill-opacity="0.04" stroke="${palette.accent}" stroke-width="1.5" stroke-opacity="0.25" stroke-dasharray="8 6" />

    <!-- 세라믹 메인 접시 그림자 -->
    <ellipse cx="400" cy="385" rx="225" ry="135" fill="#000000" fill-opacity="0.45" />

    <!-- 세라믹 메인 접시 림 (Rim) -->
    <ellipse cx="400" cy="375" rx="220" ry="130" fill="url(#plateShine)" stroke="${palette.plateRim}" stroke-width="3.5" stroke-opacity="0.8" />

    <!-- 세라믹 접시 안쪽 오목한 볼 (Bowl) -->
    <ellipse cx="400" cy="370" rx="175" ry="100" fill="#000000" fill-opacity="0.35" stroke="#FFFFFF" stroke-width="1.5" stroke-opacity="0.35" />

    <!-- 식기 일러스트: 왼쪽 포크 -->
    <g opacity="0.6" stroke="${palette.accent}" stroke-width="2.5" stroke-linecap="round">
      <line x1="120" y1="310" x2="120" y2="430" />
      <path d="M 108 310 L 108 340 Q 108 355 120 355 Q 132 355 132 340 L 132 310" fill="none" />
      <line x1="116" y1="310" x2="116" y2="345" />
      <line x1="124" y1="310" x2="124" y2="345" />
    </g>

    <!-- 식기 일러스트: 오른쪽 스푼 -->
    <g opacity="0.6" stroke="${palette.accent}" stroke-width="2.5" stroke-linecap="round">
      <line x1="680" y1="345" x2="680" y2="430" />
      <ellipse cx="680" cy="325" rx="14" ry="22" fill="none" />
    </g>

    <!-- 모락모락 피어오르는 온기 스팀 라인 -->
    <g opacity="0.55" stroke="#FFFFFF" stroke-width="3.5" stroke-linecap="round" fill="none">
      <path d="M 360 250 Q 345 210 365 180 Q 385 150 365 120" />
      <path d="M 400 235 Q 418 200 400 165 Q 382 130 402 100" stroke-width="4" opacity="0.7" />
      <path d="M 440 250 Q 455 210 435 180 Q 415 150 435 120" />
    </g>

    <!-- 중앙 대형 음식 이모지 아트워크 -->
    <text x="400" y="385" text-anchor="middle" dominant-baseline="central" font-size="145" font-family="'Apple Color Emoji', 'Segoe UI Emoji', 'Noto Color Emoji', sans-serif">${emoji}</text>
  </g>

  <!-- 하단 에디토리얼 메뉴 카드 플레이트 -->
  <g id="bottom-card" transform="translate(40, 545)">
    <!-- 카드 배경 섀도우 & 패널 -->
    <rect x="0" y="0" width="720" height="205" rx="24" fill="url(#cardGrad)" stroke="${palette.accent}" stroke-width="1.5" stroke-opacity="0.45" />

    <!-- 영문 메뉴명 (상단 서브) -->
    <text x="360" y="42" text-anchor="middle" fill="${palette.accent}" font-family="'Pretendard', -apple-system, sans-serif" font-size="16" font-weight="700" letter-spacing="1.2">${escapeXml(englishName)}</text>

    <!-- 한글 메뉴명 (메인 타이틀) -->
    <text x="360" y="86" text-anchor="middle" fill="#FFFFFF" font-family="'Pretendard', -apple-system, sans-serif" font-size="30" font-weight="800">${escapeXml(displayName)}</text>

    <!-- 정보 뱃지 행: 칼로리 & 예상 가격 / 시세 -->
    <g transform="translate(360, 126)">
      <!-- 칼로리 태그 -->
      <rect x="-190" y="-16" width="180" height="32" rx="16" fill="#FFFFFF" fill-opacity="0.08" stroke="#FFFFFF" stroke-opacity="0.15" stroke-width="1" />
      <text x="-100" y="5" text-anchor="middle" fill="#FFFFFF" font-family="'Pretendard', sans-serif" font-size="14" font-weight="600">${escapeXml(caloriesText)}</text>

      <!-- 가격대 태그 -->
      <rect x="10" y="-16" width="180" height="32" rx="16" fill="#FFFFFF" fill-opacity="0.08" stroke="#FFFFFF" stroke-opacity="0.15" stroke-width="1" />
      <text x="100" y="5" text-anchor="middle" fill="${palette.accent}" font-family="'Pretendard', sans-serif" font-size="14" font-weight="600">${escapeXml(priceText)}</text>
    </g>

    <!-- 워터마크 푸터 -->
    <text x="360" y="180" text-anchor="middle" fill="#888899" font-family="'Pretendard', sans-serif" font-size="13" font-weight="500">tellmyname.app/food • AI 감성 푸드 일러스트 컬렉션</text>
  </g>
</svg>`;
}
